import { useEffect, type RefObject } from 'react';
import { loadConfigFile } from '../../engines/configEngine';

/**
 * Field-type overlay: colours the labels on the Customer 360 main page and the open tab by how the active persona's
 * requirement for that field is classified in 'Customer 360.xlsx' - Real Time (pink) or Drill Down / Select (blue).
 * The classification is generated by reference/scripts/audit_customer360_requirements.py into
 * public/config/customer360-field-access.json ('personas': requirement -> access, 'labels': page -> on-screen label ->
 * requirements). A label with no classification for the persona keeps its default colour. Colours are the
 * `--realtime` / `--drilldown` tokens (index.css). Set SHOW_REQUIREMENT_COVERAGE to false to switch it off.
 */
export const SHOW_REQUIREMENT_COVERAGE = true;

interface FieldAccessFile {
  labels?: Record<string, Record<string, string[]>>;
  personas?: Record<string, Record<string, 'real-time' | 'drill-down'>>;
}
let fieldAccess: Promise<FieldAccessFile> | undefined;
function loadFieldAccess(): Promise<FieldAccessFile> {
  fieldAccess ??= loadConfigFile<FieldAccessFile>('customer360-field-access.json').catch(() => ({}));
  return fieldAccess;
}

const norm = (t: string | null) => (t ?? '').replace(/\s+/g, ' ').trim().toLowerCase();

/** Applies `fld-realtime` / `fld-drilldown` to leaf elements whose text (or `data-req`, when the display label differs from the requirement's) is a classified label for `personaId`, on the header and `pageKey`. Real Time wins when a label stands for requirements of both kinds. */
export function useRequirementCoverage(root: RefObject<HTMLElement | null>, personaId: string | undefined, pageKey: string, ready: boolean) {
  useEffect(() => {
    if (!SHOW_REQUIREMENT_COVERAGE || !ready || !personaId) return;
    let cancelled = false;
    let observer: MutationObserver | undefined;
    void loadFieldAccess().then((file) => {
      const el = root.current;
      if (cancelled || !el) return;
      const access = file.personas?.[personaId] ?? {};
      const kinds = new Map<string, 'fld-realtime' | 'fld-drilldown'>();
      for (const page of ['header', pageKey]) {
        for (const [label, reqs] of Object.entries(file.labels?.[page] ?? {})) {
          const levels = reqs.map((r) => access[r]);
          const kind = levels.includes('real-time') ? 'fld-realtime' : levels.includes('drill-down') ? 'fld-drilldown' : undefined;
          if (kind && kinds.get(norm(label)) !== 'fld-realtime') kinds.set(norm(label), kind);
        }
      }
      const apply = () => {
        el.querySelectorAll('.fld-realtime, .fld-drilldown').forEach((n) => n.classList.remove('fld-realtime', 'fld-drilldown'));
        if (kinds.size === 0) return;
        el.querySelectorAll('*').forEach((n) => {
          // The tab rail is navigation, not content.
          // Side drawers that carry their own (non-audit) labels opt out with data-coverage-ignore.
          if (n.children.length > 0 || n.closest('ol') || n.closest('[data-coverage-ignore]')) return;
          const kind = kinds.get(norm((n as HTMLElement).dataset?.req ?? n.textContent));
          if (kind) n.classList.add(kind);
        });
      };
      apply();
      observer = new MutationObserver(apply);
      observer.observe(el, { childList: true, subtree: true, characterData: true });
    });
    return () => {
      cancelled = true;
      observer?.disconnect();
    };
  }, [root, personaId, pageKey, ready]);
}
